<?php
declare(strict_types=1);
namespace App\Application\QuestionLearning\AI;
use App\Domain\QuestionLearning\Enum\ExplanationSafetyMode;
final class QuestionExplanationResponseValidator { /** @return array{summary:string,concepts:list<string>,reinforcement:string,safety_mode:string} */ public function validate(array $payload, ExplanationSafetyMode $mode): array { $summary=$payload['summary']??null;$concepts=$payload['concepts']??null;$reinforcement=$payload['reinforcement']??null;if(!is_string($summary)||!is_array($concepts)||!is_string($reinforcement)||mb_strlen(trim($summary))<3||mb_strlen($summary)>3000||mb_strlen(trim($reinforcement))<3||mb_strlen($reinforcement)>1500||count($concepts)>8||array_filter($concepts,static fn(mixed $concept):bool=>!is_string($concept)||trim($concept)===''))throw new \InvalidArgumentException('Resposta de explicação inválida.');$result=['summary'=>trim($summary),'concepts'=>array_values(array_map('trim',$concepts)),'reinforcement'=>trim($reinforcement),'safety_mode'=>$mode->value];if($mode===ExplanationSafetyMode::CONCEPTUAL_ONLY&&preg_match('/\b(gabarito|alternativa\s+(correta|[A-E])|resposta\s+correta)\b/iu',$result['summary'].' '.$result['reinforcement']))throw new \InvalidArgumentException('Explicação revelou conteúdo não permitido.');return $result;} public function jsonSchema():array{return ['type'=>'object','additionalProperties'=>false,'required'=>['summary','concepts','reinforcement'],'properties'=>['summary'=>['type'=>'string','maxLength'=>3000],'concepts'=>['type'=>'array','maxItems'=>8,'items'=>['type'=>'string']],'reinforcement'=>['type'=>'string','maxLength'=>1500]]];} }
